referenceSolutions.javascript:
export function solve(left, right, key) {
  const allowed = new Set(right.map((x) => x[key]));
  const seen = new Set();
  return left.filter((x) => {
    const k = x[key];
    if (!allowed.has(k) || seen.has(k)) return false;
    seen.add(k);
    return true;
  });
}

